import{_ as o,c as t,b as a,a2 as s}from"./chunks/framework.BEqfOpL-.js";const u=JSON.parse('{"title":"FAQ","description":"PodSEO offers multiple plans to fit different needs — from independent podcasters to agencies managing multiple shows. Each plan includes different features, such as keyword tracking limits, access to visibility insights, and competitor discovery tools.","frontmatter":{},"headers":[],"relativePath":"more/faq.md","filePath":"more/faq.md"}'),r={name:"more/faq.md"};function n(i,e,l,d,h,c){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h3 id="what-are-the-pricing-plans-for-podseo" tabindex="-1">What are the pricing plans for PodSEO? <a class="header-anchor" href="#what-are-the-pricing-plans-for-podseo" aria-label="Permalink to &quot;What are the pricing plans for PodSEO?&quot;">​</a></h3><p>PodSEO offers multiple plans to fit different needs — from independent podcasters to agencies managing multiple shows. Each plan includes different features, such as keyword tracking limits, access to visibility insights, and competitor discovery tools.</p><p>You can find the full breakdown of our pricing and features on our <a href="https://podseo.com/pricing/" target="_blank" rel="noreferrer">Pricing Page</a>.</p><br><h3 id="is-there-a-free-version-of-podseo" tabindex="-1">Is there a free version of PodSEO? <a class="header-anchor" href="#is-there-a-free-version-of-podseo" aria-label="Permalink to &quot;Is there a free version of PodSEO?&quot;">​</a></h3><p>Yes! PodSEO offers a free version with specific limitations — perfect if you&#39;re just getting started. Here&#39;s what you get:</p><p><strong>Free Plan Includes:</strong></p><ul><li><strong><a href="/features/keyword-strategy.html">Keyword Strategy</a></strong>: Up to 5 tracked keywords in total, which you can use for your show, your episodes, your brand, competitors or themes</li><li><strong><a href="/features/show-visibility.html">Show Visibility</a></strong>: In Search Appearances, you see every keyword row with its rankings and search volume; your 3 best-ranked keywords are shown in clear and the others are masked (upgrade to see them all)</li><li><strong><a href="/features/show-optimization.html">Show optimization</a></strong>: Review how your show title, author, and description align with your show keywords</li><li><strong><a href="/features/planner.html">Planner</a></strong>: Plan up to 3 active episodes and assign each episode its own keywords; AI episode suggestions require a paid plan</li><li><strong><a href="/features/analytics.html">Analytics</a></strong>: Connect listening sources on every plan; YouTube offers a limited Free view</li><li><strong><a href="/features/competitive-analysis.html">Competitors</a></strong>: Track up to 2 competitors</li><li><strong>Credits</strong>: 10 monthly credits for actions such as episode analysis and clip creation</li><li><strong><a href="/features/lucia-ai-assistant.html">LUCIA AI Chat</a></strong>: 5 messages per month</li><li><strong><a href="/features/keyword-tracker.html">Keyword Tracker</a></strong>: Full access to tracking charts and historical data</li><li><strong>Basic Platform Data</strong>: Rankings across Apple Podcasts, Spotify, Amazon Music, and YouTube Music</li></ul><p><strong>Paid Plan Benefits:</strong></p><ul><li><strong>Full Visibility</strong>: Unlock all keyword rankings in <a href="/features/show-visibility.html">Show Visibility</a></li><li><strong>A much larger keyword allowance</strong>: Podcaster 100, Producer 500, Agency 50,000 tracked keywords in total</li><li><strong>Complete Metadata Analysis</strong>: AI suggestions for show metadata in <a href="/features/show-optimization.html">Show optimization</a>, and episode suggestions in Planner</li><li><strong>Advanced Features</strong>: Enhanced <a href="/features/competitor-finder.html">competitor discovery</a> and premium analytics</li></ul><p>When you&#39;re ready to unlock the full platform, you can upgrade at any time. Learn more on our <a href="https://podseo.com/pricing/" target="_blank" rel="noreferrer">Pricing Page</a>.</p><br><h3 id="what-are-show-episode-brand-competitor-and-theme-keywords" tabindex="-1">What are show, episode, brand, competitor and theme keywords? <a class="header-anchor" href="#what-are-show-episode-brand-competitor-and-theme-keywords" aria-label="Permalink to &quot;What are show, episode, brand, competitor and theme keywords?&quot;">​</a></h3><p>Every tracked keyword says what it&#39;s for. A keyword can serve the show and several episodes at once.</p><p><strong>Show Keywords</strong> (start with 2-3, aim for about 5, with 2 in your show title):</p><ul><li>Your most important target keywords for your show title, author and description</li><li>Generate the deepest analysis and recommendations</li><li>Should represent your core podcast topics</li></ul><p><strong>Episode Keywords</strong> (about 2-3 per episode, on every plan):</p><ul><li>Guide the title and description of one planned or published episode</li><li>Provide broader topic coverage and discovery opportunities</li></ul><p><strong>Brand, Guest, Competitor and Theme Keywords</strong>:</p><ul><li>Your show or host name, a guest&#39;s name, a competitor&#39;s terms, or a group of keywords</li><li>Tracked and analyzed, never scored against your metadata</li><li>Perfect for competitive intelligence and market monitoring</li></ul><p>A keyword you haven&#39;t assigned yet stays <strong>Unassigned</strong>: it is still tracked, and PodSEO suggests an episode when the keyword already appears in one.</p><p><strong>How the allowance works:</strong> each plan has one total keyword allowance shared across every podcast in your account (Free 5, Podcaster 100, Producer 500, Agency 50,000). Every tracked keyword draws from that pool, whatever it&#39;s used for; there is no separate cap per kind. Adding a second podcast does not add a second allowance.</p><p>Learn more about building your keyword strategy in our <a href="/features/keyword-strategy.html">Keyword Strategy guide</a> or follow our step-by-step <a href="/getting-started/workflow.html">PodSEO Workflow</a>.</p><br><h3 id="how-often-should-i-check-my-metadata-alignment" tabindex="-1">How often should I check my metadata alignment? <a class="header-anchor" href="#how-often-should-i-check-my-metadata-alignment" aria-label="Permalink to &quot;How often should I check my metadata alignment?&quot;">​</a></h3><p>Review show metadata in <strong>Content → <a href="/features/show-optimization.html">Show Optimization</a></strong> and individual episodes in <strong>Content → <a href="/features/planner.html">Episode Planner</a></strong>:</p><ul><li><strong>Initially</strong>: After adding your podcast and setting up your keyword strategy</li><li><strong>After Changes</strong>: Whenever you update your cover art, description, or add new episodes</li><li><strong>Monthly</strong>: As a regular optimization check to discover new opportunities</li><li><strong>Before Big Launches</strong>: Prior to major episode releases or series launches</li></ul><p>For show-wide suggestions on a paid plan, click <strong>Get AI suggestions for your podcast</strong> in Show optimization. In Planner, open the episode you want to improve and review its own keywords and suggestions.</p><br><h3 id="why-do-i-see-different-rankings-on-different-platforms" tabindex="-1">Why do I see different rankings on different platforms? <a class="header-anchor" href="#why-do-i-see-different-rankings-on-different-platforms" aria-label="Permalink to &quot;Why do I see different rankings on different platforms?&quot;">​</a></h3><p>Each podcasting platform runs its own search, and none of them publishes its full ranking formula. What they do say:</p><p><strong>Apple Podcasts</strong>: Search is ordered by metadata (show name, channel name, episode titles), popularity (followers and plays), and engagement from search results. Ratings and reviews aren&#39;t a direct search input, but they reflect the listening and follows that are. In PodSEO&#39;s observations the Author field also appears to matter more than most creators expect on Apple. <strong>Spotify</strong>: Recommends searchable titles and descriptions (first 250 characters), transcripts, chapters, and topic/guest tags; click-through from search influences relevance. <strong>Amazon Music</strong> and <strong>YouTube Music</strong>: Neither publishes search guidance for podcasts; YouTube Music behaves like a video platform with its own search and recommendations.</p><p>This is why PodSEO tracks all major platforms — what works on one platform may need adjustment for others. Use <a href="/features/show-visibility.html">Show Visibility</a> to see your performance across all platforms, <a href="/features/competitive-analysis.html">Competitive Analysis</a> to see how competitors rank, and the <a href="/academy/platform-algorithm-deep-dive-how-spotify-vs-apple-podcasts-really-rank-shows.html">platform algorithm guide</a> for what&#39;s documented versus assumed.</p><br><h3 id="why-are-my-rankings-different-from-what-i-see-in-my-own-podcast-app" tabindex="-1">Why are my rankings different from what I see in my own podcast app? <a class="header-anchor" href="#why-are-my-rankings-different-from-what-i-see-in-my-own-podcast-app" aria-label="Permalink to &quot;Why are my rankings different from what I see in my own podcast app?&quot;">​</a></h3><p>PodSEO collects rankings as a neutral listener in the <strong>United States</strong> sees them. Your own app shows results for your device&#39;s country, language, and sometimes your listening history, so small differences are normal. If your audience is mainly outside the US, paid plans let you add search countries per podcast in <strong>Settings → Shows</strong> and switch between them in <a href="/features/keyword-tracker.html#search-countries">Keyword Tracker</a> (Podcaster 1 additional country, Producer 5, Agency 10). Search countries are separate from chart countries and review storefronts.</p><br><h3 id="what-does-keyword-search-volume-mean" tabindex="-1">What does keyword search volume mean? <a class="header-anchor" href="#what-does-keyword-search-volume-mean" aria-label="Permalink to &quot;What does keyword search volume mean?&quot;">​</a></h3><p>Search volume is a relative indicator of interest in a keyword. Some accounts see a six-step meter; its levels, from lowest to highest, are <strong>Very niche</strong>, <strong>Niche</strong>, <strong>Small</strong>, <strong>Medium</strong>, <strong>Popular</strong>, and <strong>Very popular</strong>. Others see a numerical Volume score. Neither is a count of monthly searches.</p><p>Where the meter is available, hover over it or focus it with the keyboard to read its level. A clock icon means the keyword has not been measured yet; its level appears after a periodic check.</p><p>Volume is one input to your decision, not a guarantee of listeners or an indication that a keyword is right for your show. Consider relevance, Difficulty and Popularity alongside it when choosing a mix of terms.</p><br><h3 id="how-long-does-it-take-to-see-results-from-optimization" tabindex="-1">How long does it take to see results from optimization? <a class="header-anchor" href="#how-long-does-it-take-to-see-results-from-optimization" aria-label="Permalink to &quot;How long does it take to see results from optimization?&quot;">​</a></h3><p>There is no fixed timeline, because platforms don&#39;t publish how quickly they re-index metadata or how heavily they weight popularity signals. What you can expect:</p><p><strong>Soon after a change</strong>:</p><ul><li>Your updated title or description appears on the platforms once your host&#39;s feed refreshes and each platform re-fetches it (usually hours to a few days)</li><li>New keywords begin tracking in PodSEO with the next ranking collection</li></ul><p><strong>Over the following weeks</strong>:</p><ul><li>Metadata-driven position changes for the keywords you targeted often show up within a few weeks; watch them in <a href="/features/keyword-tracker.html">Keyword Tracker</a></li><li>Popularity-driven movement (followers, plays, completions) builds more slowly and depends on how many new listeners your episodes attract</li></ul><p>Rather than waiting for a promised milestone, compare each keyword against its own starting position, give a change at least a few weeks and a new episode or two before judging it, and keep applying recommendations consistently. The <a href="/academy/podcast-analytics-decoded-which-metrics-actually-matter-for-seo.html">analytics guide</a> explains a review routine.</p><br><h3 id="what-happens-after-i-add-a-podcast" tabindex="-1">What happens after I add a podcast? <a class="header-anchor" href="#what-happens-after-i-add-a-podcast" aria-label="Permalink to &quot;What happens after I add a podcast?&quot;">​</a></h3><p>When you add a podcast, PodSEO sets up your baseline across Apple Podcasts, Spotify, Amazon Music, and YouTube Music — capturing your current rankings, the keywords you already appear for, and similar podcasts in your category. This gives you a starting point to measure your optimization efforts against.</p><p>Your dashboard will populate as this information becomes available, and you&#39;ll be notified when everything is ready to explore.</p><br><h3 id="my-show-is-already-on-apple-podcasts-or-spotify-why-connect-analytics" tabindex="-1">My show is already on Apple Podcasts or Spotify. Why connect analytics? <a class="header-anchor" href="#my-show-is-already-on-apple-podcasts-or-spotify-why-connect-analytics" aria-label="Permalink to &quot;My show is already on Apple Podcasts or Spotify. Why connect analytics?&quot;">​</a></h3><p>Being listed on a listening platform makes your show available to listeners. Connecting analytics gives PodSEO permission to read that platform&#39;s reports, so you can see listening data alongside your search visibility. These are separate steps, and connecting analytics does not publish or change your show.</p><p>Open <strong>Analytics</strong> and choose the source you want to connect. See <a href="/features/analytics-connections.html">Connect Your Analytics</a> for the steps for Apple Podcasts, Spotify, YouTube and supported hosts.</p><br><h3 id="where-do-i-find-the-code-to-connect-spotify" tabindex="-1">Where do I find the code to connect Spotify? <a class="header-anchor" href="#where-do-i-find-the-code-to-connect-spotify" aria-label="Permalink to &quot;Where do I find the code to connect Spotify?&quot;">​</a></h3><p>Open <strong>Analytics → Spotify</strong> and click <strong>Connect Spotify</strong>. PodSEO shows a code to paste into the <strong>Title</strong> field of the invitation to <code>spotify@podseo.com</code>. After sending the invitation with Analytics access set to Reader, return to PodSEO and click <strong>I&#39;ve sent the invite</strong>. Follow the status card while access is confirmed and reports are imported.</p><p>If someone else manages your Spotify team, send them the steps and your code. See the full <a href="/features/analytics-connections.html#spotify-for-creators">Spotify connection instructions</a> for permissions and troubleshooting.</p><br><h3 id="apple-podcasts-is-already-showing-podseo-as-an-analyst-why-is-my-connection-still-waiting" tabindex="-1">Apple Podcasts is already showing PodSEO as an Analyst. Why is my connection still waiting? <a class="header-anchor" href="#apple-podcasts-is-already-showing-podseo-as-an-analyst-why-is-my-connection-still-waiting" aria-label="Permalink to &quot;Apple Podcasts is already showing PodSEO as an Analyst. Why is my connection still waiting?&quot;">​</a></h3><p>Check the status card in <strong>Analytics → Apple Podcasts</strong> for the next step. PodSEO may still need to confirm ownership or import reports after an invitation is accepted. Make sure the invitation grants access to the correct show; the <a href="/features/analytics-connections.html#apple-podcasts-connect">Apple connection guide</a> explains the ownership checks.</p><p>If the status remains unclear, <a href="https://podseo.com/settings/contact" target="_blank" rel="noreferrer">contact support</a> with the show&#39;s Apple Podcasts link and the status shown in PodSEO. If you see duplicate listings, ask for help identifying the correct one before removing either listing.</p><br><h3 id="my-host-distributes-my-show-to-apple-but-i-can-t-find-it-in-apple-podcasts-connect-what-can-i-do" tabindex="-1">My host distributes my show to Apple, but I can&#39;t find it in Apple Podcasts Connect. What can I do? <a class="header-anchor" href="#my-host-distributes-my-show-to-apple-but-i-can-t-find-it-in-apple-podcasts-connect-what-can-i-do" aria-label="Permalink to &quot;My host distributes my show to Apple, but I can&#39;t find it in Apple Podcasts Connect. What can I do?&quot;">​</a></h3><p>Your host may have submitted the show using its own Apple account. You may be able to claim the existing show in your own Apple Podcasts Connect account, then invite PodSEO as an Analyst. Check the show name and artwork before claiming it. If your host has no Apple claim-token field, ask your host&#39;s support for help.</p><p>The <a href="/features/analytics-connections.html#apple-podcasts-connect">claiming instructions</a> explain the steps and cases where claiming is unavailable. Do not create or remove a listing just to connect analytics.</p><br><h3 id="can-i-track-keywords-i-m-not-currently-ranking-for" tabindex="-1">Can I track keywords I&#39;m not currently ranking for? <a class="header-anchor" href="#can-i-track-keywords-i-m-not-currently-ranking-for" aria-label="Permalink to &quot;Can I track keywords I&#39;m not currently ranking for?&quot;">​</a></h3><p>Yes! Track any keyword and leave it unassigned (or assign it to a competitor or theme), whether you&#39;re currently ranking or not. This is perfect for:</p><ul><li><strong>Competitor Analysis</strong>: Track keywords your competitors rank for</li><li><strong>Market Research</strong>: Monitor emerging trends in your niche</li><li><strong>Future Strategy</strong>: Watch keywords you plan to target later</li><li><strong>Performance Goals</strong>: Track progress toward ranking for new terms</li></ul><p>These keywords count toward your plan&#39;s total keyword allowance.</p><p>Unassigned terms can contribute to your show-description alignment and suggestions. An episode without its own keywords uses your show keywords, then Unassigned terms if no show keywords are set.</p><p>Assigning a term only to a competitor or theme does not make it a metadata target; an additional Show or Episode target still does. Learn more in our <a href="/features/keyword-strategy.html">Keyword Strategy guide</a> or explore <a href="/features/competitor-finder.html">competitor discovery tools</a> to find new keywords to track.</p><h3 id="can-podseo-show-how-my-podcast-performs-on-youtube" tabindex="-1">Can PodSEO show how my podcast performs on YouTube? <a class="header-anchor" href="#can-podseo-show-how-my-podcast-performs-on-youtube" aria-label="Permalink to &quot;Can PodSEO show how my podcast performs on YouTube?&quot;">​</a></h3><p>Yes. Connect your podcast&#39;s YouTube channel and activate <a href="/features/youtube-insights.html">YouTube Insights</a> (<strong>Analytics → YouTube</strong>). You&#39;ll see your channel&#39;s views, watch hours, subscriber change, where your views come from, and the real searches that bring viewers to your videos, compared with the keywords you track in PodSEO. PodSEO also matches your videos to your podcast episodes and suggests tracked keywords to add to your video titles.</p><p>The connection is read-only: PodSEO never edits your videos. It&#39;s the same connection used to publish Shorts from <a href="/features/social-publishing.html">Social</a>. YouTube Insights is available on every plan; the free plan covers channel performance, one search term, and your latest episode, while paid plans unlock every search term and your recent episodes.</p><p><strong>YouTube vs YouTube Music</strong>: YouTube Music is the podcast directory inside the YouTube Music app, and PodSEO tracks your podcast rankings there like on Apple and Spotify. YouTube Insights is about your <strong>YouTube channel</strong> and its videos.</p><br><hr><h2 id="need-more-help" tabindex="-1">Need More Help? <a class="header-anchor" href="#need-more-help" aria-label="Permalink to &quot;Need More Help?&quot;">​</a></h2><ul><li><strong>Getting Started</strong>: Follow our <a href="/getting-started/first-steps.html">step-by-step first steps guide</a> or <a href="/getting-started/workflow.html">PodSEO Workflow</a></li><li><strong>Something not working?</strong>: See <a href="/more/troubleshooting.html">Troubleshooting</a></li><li><strong>Feature Documentation</strong>: Browse our complete feature guides for detailed instructions</li><li><strong>AI Assistant</strong>: Chat with <a href="/features/lucia-ai-assistant.html">LUCIA</a> for personalized help and answers</li><li><strong>Contact Support</strong>: Reach out via <a href="https://podseo.com/settings/contact" target="_blank" rel="noreferrer">Settings → Contact Us</a> for additional assistance</li></ul><p>For account questions, see <a href="/features/billing-and-account.html">Billing and Account Settings</a> and <a href="/features/teams-and-organizations.html">Teams and Organizations</a>. Client reporting and approvals are covered in <a href="/features/agency-workspace.html">Agency Workspace</a>.</p>',86)])])}const f=o(r,[["render",n]]);export{u as __pageData,f as default};
